from pathlib import Path
import json,re,subprocess,shlex
p=Path('review/test-defend/stage1-cohere-yaml-compose')
plan=json.loads((p/'plan.json').read_text());matrix=json.loads((p/'matrix.json').read_text())
def family(n):
 if re.fullmatch('TestFileDriver_[0-9]+',n):return 'TestFileDriver family'
 if re.fullmatch('TestScalarsMatchGo_[0-9]+',n):return 'TestScalarsMatchGo family'
 return n
rows=[];validation=[]
for m in plan:
 runs=[r for r in matrix if r['mutant']==m['id']]
 failed=sorted({family(n) for r in runs for n in r['failed']});passed=sorted({family(n) for r in runs for n in r['passed'] if n!='TestFileDriver_Setup'} - set(failed));unknown=sorted({r['row'] for r in runs if r['cooked']} - {r['row'] for r in runs if not r['cooked'] and r['exit'] in [0,1]})
 caught=next((r for r in runs if m['target'] in [family(n) for n in r['failed']]),None)
 defense='defended' if caught and failed==[m['target']] and not unknown else 'cannot-judge'
 rows.append(dict(test=m['target'],package='stage1/cohere/yaml',prior_verdict='subsumed',subsumed_by=['TestFileDriver family' if m['id']=='D2' else 'TestFormatterMatchesGo'],defense=defense,unique_mutant=f"{m['id']} {m['file']}:{m['line']}" if defense=='defended' else None,attempts=[dict(mutant=m['id'],file_line=f"{m['file']}:{m['line']}",change=m['old']+' -> '+m['new'],rows_failed=failed)],evidence=(f"ADAMIC_NATIVE_SPLIT=1 ADAMIC_YAML_LIBRARY=/tmp/defend-yaml/library ADAMIC_BUILD_CACHE_DIR=/tmp/defend-yaml/cache/{m['id']} "+shlex.join(caught['command'])+'; '+caught['assertions'][0]) if caught else 'No completed target failure',bounded=True,matrix_rows=sorted({family(n) for r in runs for n in r['passed']+r['failed'] if n!='TestFileDriver_Setup'}),rows_passed=passed,unknown_rows=unknown,diff=m['id']+'.diff',failed_members=sorted({n for r in runs for n in r['failed']}),members=[f'TestFileDriver_{i:03d}' for i in range(8)] if m['id']=='D3' else []))
 validation.append(dict(mutant=m['id'],applies_to='bfe0553300773c0b37db2c10df97adeb909705f8',native_build='successful native execution recorded before assertion' if caught else 'inspect logs',assertion=caught['assertions'][0] if caught else None,cache='/tmp/defend-yaml/cache/'+m['id'],options='native.Options{Sanitize:true}, ADAMIC_NATIVE_SPLIT=1'))
(p/'rows.json').write_text(json.dumps(rows,indent=2)+'\n');(p/'validation.json').write_text(json.dumps(validation,indent=2)+'\n')
summary='\n'.join([f"{r['test']}: {r['defense']} using {r['unique_mutant']}" for r in rows])
(p/'report.md').write_text(summary+'\n\n'+json.dumps(rows,indent=2)+'\n\nBounded matrices inspect functional agreement guards. Other packages and production-independent setup/witness rows remain outside these uniqueness claims. All current names were compared with the audit: 72 names, no additions or disappearances.\n\nFriction and limits\n\nThe outer whole-package baseline cooked at 120 seconds; file-driver setup passed at 76.89 seconds before that. Clean solo composer/CST/file coverage runs passed. The optional library install initially omitted yaml-unist-parser@3.2.0; TestUnistMatchesGo failed solely with ERR_MODULE_NOT_FOUND, then passed after installation, before mutations. Formatter clean runs cooked at 90 seconds; supported split compilation reached its independent original-library comparison after port agreement had completed. Mutant formatter runs and final restored runs are recorded separately. No timeout is counted as a kill.\n\nGo -coverpkg profiles do not instrument TypeScript. The file-driver parent misses its cached setup child, so its apparent lack of compiler coverage is not proof of exclusive port execution. Semantic differences and mutation evidence establish the defenses. The supplied audit evidence excerpts were truncated; the full prior report, matrix, inventory, and plan are preserved.\n\nThese rows name semantic agreement, and assert exact external observations; no missing performance threshold or name/assertion mismatch was found. No separate executor twins exist among the three target rows. No tests, oracle adapters, or original library code were changed.\n\nTiming: warm toolchain, setup skipped, nproc=5. Initial npm install times were not separately instrumented. Matrix shell wall total '+str(round(sum(r['wall'] for r in matrix),2))+' seconds, including lowering, native rebuilds, Go oracle builds, and external executors. Per-command times and distinct caches are in matrix.json. Go coverage commands and timings are in coverage-runs.json. No separate lowering-versus-clang timing is claimed.\n')
print(summary)
